    if (!text) return [];
    var matches = [];
    var m;
    var re = new RegExp(CLOSING_KEYWORD_PATTERN.source, 'gi');
    while ((m = re.exec(text)) !== null) {
        matches.push(m[0]);
        if (matches.length > 20) break; // safety valve for pathological input
